import{_ as e,o,c as t,a2 as i}from"./chunks/framework.CHeM0PsO.js";const f=JSON.parse('{"title":"工具链-BBDown/ffmpeg/aria2","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/features/tools.md","filePath":"projects/lotus-plugin/docs/features/tools.md"}'),s={name:"projects/lotus-plugin/docs/features/tools.md"};function n(r,a,l,d,c,p){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="工具链-bbdown-ffmpeg-aria2" tabindex="-1">工具链-BBDown/ffmpeg/aria2 <a class="header-anchor" href="#工具链-bbdown-ffmpeg-aria2" aria-label="Permalink to &quot;工具链-BBDown/ffmpeg/aria2&quot;">​</a></h1><p>返回：<a href="./../initialization.html">上一级</a> / <a href="./../README.html">文档目录</a> / <a href="./README.html">小功能索引</a></p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><ul><li>自动准备 B 站下载所需的 BBDown、ffmpeg、ffprobe、ffplay 和 aria2c。</li><li>Windows 识别 <code>.exe</code> 文件；Linux/macOS 识别无后缀可执行文件，并在初始化时补 <code>chmod +x</code>。</li><li>下载到损坏压缩包、不完整 shared 包或 <code>.part</code> 临时文件时，会清理后重新下载。</li><li>B 站下载固定走 BBDown，ffmpeg 和 aria2c 只作为配套工具链。</li></ul><h2 id="指令用法" tabindex="-1">指令用法 <a class="header-anchor" href="#指令用法" aria-label="Permalink to &quot;指令用法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#初始化工具环境</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="变量说明" tabindex="-1">变量说明 <a class="header-anchor" href="#变量说明" aria-label="Permalink to &quot;变量说明&quot;">​</a></h2><p>此指令没有额外变量。初始化结果会写入运行时缓存目录，正常使用时不需要手动移动工具文件。</p><p>BBDown 默认使用 <code>MOPELotus/BBDown</code> 的 <code>1.6.4</code> 修复版。旧配置中的 <code>nilaoda/BBDown</code> 会自动迁移。开机检测实际下载工具目录中的版本；不等于 <code>1.6.4</code>（含缺失或无法识别）时，在机器人进程启动五分钟后重新检测，通知主人并自动更新。关闭工具自动安装或禁用 BBDown 时跳过。下载、执行版本验证成功后才替换旧程序；现有软链接替换为插件管理的可执行文件，不修改外部链接目标，保留目录中的登录文件。支持 Linux/macOS/Windows 的 x64、arm64 直接可执行附件。</p>',9)])])}const u=e(s,[["render",n]]);export{f as __pageData,u as default};
